const RECOVER_SCRIPT = "return redis.call('GET', KEYS[1])";
export function encodeBytes(value) {
  return Buffer.from(value).toString('base64');
}
export function decodeBytes(text) {
  return new Uint8Array(Buffer.from(text, 'base64'));
}
export async function recover(client, key) {
  return client.eval(RECOVER_SCRIPT, 1, key);
}

